sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
	var startDateStr = g_form.getValue('start_date');
	var endDateStr = g_form.getValue('end_date');

	var startDate = getDateFromFormat(startDateStr, g_user_date_format);
	var endDate = getDateFromFormat(endDateStr, g_user_date_format);

	var diffInMs = endDate - startDate;
    var days = diffInMs / (1000 * 60 * 60 * 24);

	if((days>2)&&(newValue=='sick')) {
		g_form.setMandatory('document_attachment', 'true');
		g_form.setDisplay('document_attachment', 'true');
	}

}
